/**
 * Astronomy's evidence states are the subset of the shared empirical axis that
 * this layer can produce. The `satisfies` clause is load-bearing: it makes any
 * future divergence from the shared vocabulary a compile error rather than a
 * second private enum that happens to overlap.
 */
export const ASTRONOMY_EVIDENCE_STATES = ['direct-observation', 'calibrated-measurement', 'method-basis', 'model-dependent', 'consensus-summary', 'open-question'] as const satisfies readonly ClaimEmpiricalStatus[]
export type AstronomyEvidenceState = typeof ASTRONOMY_EVIDENCE_STATES[number]

export const ASTRONOMY_FACT_FIELDS = [
  'time.utcInstant', 'time.ephemerisTimeScale', 'observer.position', 'observer.uncertainty',
  'subject.identifiers', 'reference.origin', 'reference.frame', 'reference.epoch',
  'reference.corrections', 'coordinates.values', 'coordinates.uncertainty', 'provenance.provider',
] as const
export type AstronomyFactField = typeof ASTRONOMY_FACT_FIELDS[number]

export interface AstronomySource {
  id: string
  title: string
  publisher: string
  url: string
  authorityTier: 'standard' | 'mission-documentation' | 'scientific-archive' | 'institutional-synthesis'
  accessed: string
  establishes: string
  boundary: string
}

export interface AstronomyClaim {
  id: string
  statement: string
  /** The empirical axis. Named `evidenceState` for continuity with 0.1 records. */
  evidenceState: AstronomyEvidenceState
  /** The provenance axis: how faithfully the claim represents its sources. */
  provenance: ClaimProvenance
  sourceIds: string[]
  boundary: string
}

export interface AstronomySection {
  heading: string
  paragraphs: string[]
  claimIds: string[]
}

export interface AstronomyArticle {
  id: string
  slug: string
  title: string
  shortTitle: string
  description: string
  definition: string
  track: AstronomyTrack
  kind: AstronomyKind
  status: 'FOUNDATIONAL' | 'ACTIVE' | 'DEVELOPING'
  datePublished: string
  dateModified: string
  measured: string[]
  inferred: string[]
  assumptions: string[]
  limitations: string[]
  factDependencies: AstronomyFactField[]
  claims: AstronomyClaim[]
  sections: AstronomySection[]
  sourceIds: string[]
  relatedArticleIds: string[]
}

