export const ASTRONOMY_KNOWLEDGE_REGISTRY = {
  version: ASTRONOMY_KNOWLEDGE_VERSION,
  releasedOn: ASTRONOMY_KNOWLEDGE_RELEASE_DATE,
  factLayer: `${SITE_URL}/knowledge/celestial`,
  schema: `${SITE_URL}${ASTRONOMY_SCHEMA_PATH}`,
  articles: ASTRONOMY_ARTICLES,
  sources: ASTRONOMY_SOURCES,
} as const

export function astronomyArticlePath(article: Pick<AstronomyArticle, 'slug'>): string {
  return `${ASTRONOMY_KNOWLEDGE_PATH}/${article.slug}`
}

export function getAstronomyArticle(id: string): AstronomyArticle | undefined {
  return ASTRONOMY_ARTICLES.find((article) => article.id === id)
}

export function getAstronomyArticleBySlug(slug: string): AstronomyArticle | undefined {
  return ASTRONOMY_ARTICLES.find((article) => article.slug === slug)
}

export function assertAstronomyKnowledgeIntegrity(): void {
  const sourceIds = new Set(ASTRONOMY_SOURCES.map((source) => source.id))
  const articleIds = new Set(ASTRONOMY_ARTICLES.map((article) => article.id))
  if (sourceIds.size !== ASTRONOMY_SOURCES.length) throw new Error('Astronomy source identifiers must be unique.')
  if (articleIds.size !== ASTRONOMY_ARTICLES.length) throw new Error('Astronomy article identifiers must be unique.')
  if (new Set(ASTRONOMY_ARTICLES.map((article) => article.slug)).size !== ASTRONOMY_ARTICLES.length) throw new Error('Astronomy article slugs must be unique.')
  for (const track of ASTRONOMY_TRACKS) if (!ASTRONOMY_ARTICLES.some((article) => article.track === track)) throw new Error(`Astronomy track ${track} has no coverage.`)
  for (const source of ASTRONOMY_SOURCES) {
    if (!source.url.startsWith('https://')) throw new Error(`${source.id} must use HTTPS.`)
    if (source.establishes.length < 80 || source.boundary.length < 80) throw new Error(`${source.id} needs explicit scope and boundary.`)
  }
  for (const article of ASTRONOMY_ARTICLES) {
    if (article.definition.length < 120 || article.claims.length < 3 || article.sections.length < 3) throw new Error(`${article.id} is not substantive.`)
    if (article.measured.length < 3 || article.inferred.length < 3 || article.assumptions.length < 3 || article.limitations.length < 3) throw new Error(`${article.id} needs a full evidence contract.`)
    for (const sourceId of article.sourceIds) if (!sourceIds.has(sourceId)) throw new Error(`${article.id} references missing source ${sourceId}.`)
    for (const relatedId of article.relatedArticleIds) if (!articleIds.has(relatedId)) throw new Error(`${article.id} references missing article ${relatedId}.`)
    for (const claim of article.claims) {
      if (claim.sourceIds.length === 0 || claim.boundary.length < 30) throw new Error(`${claim.id} lacks evidence or a boundary.`)
      assertClaimEvidence({ provenance: claim.provenance, empirical: claim.evidenceState }, claim.id)
      for (const sourceId of claim.sourceIds) if (!sourceIds.has(sourceId)) throw new Error(`${claim.id} references missing source ${sourceId}.`)
    }
  }
}

assertAstronomyKnowledgeIntegrity()
